#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MOTOR DE RÉPLICAS · CONSIGNADO INSS
Ronney Menezes Advocacia

Arquivo único. Lê o processo inteiro, cruza a petição inicial com a contestação
e com os documentos juntados pelos dois lados, aponta as lacunas e as falhas de
cada um, e monta a réplica correspondente a partir do Caderno de Réplicas, 2ª
edição, que vem inteiro dentro deste arquivo.

Uso:   python3 MotorReplicas.py
       abre sozinho em http://127.0.0.1:8777

Papel timbrado: coloque o .docx do timbrado na subpasta "timbrado", ao lado
deste arquivo. As peças e os relatórios gerados vão para a subpasta "pecas".

Requisitos: python-docx, poppler e tesseract. O programa confere e diz o que
falta ao arrancar.

Roda inteiramente na máquina local. Nenhum dado de processo sai do computador:
não há chamada de rede, não há serviço externo e não há modelo de linguagem em
ponto algum do caminho. A leitura é feita com expressões regulares e aritmética;
a montagem é substituição de texto que já existe no caderno.

Este arquivo é gerado por construir_arquivo_unico.py a partir dos módulos
forense.py, leitor.py, processual.py e motor_replicas.py. Para alterar o
programa, altere os módulos e gere de novo, ou edite as fontes embutidas abaixo
com cuidado, porque elas estão comprimidas.
"""

import base64
import os
import sys
import types
import zlib

_MOD = {}


def _abrir(pedacos):
    return zlib.decompress(base64.b64decode("".join(pedacos))).decode("utf-8")


def _carregar(nome, fonte, extras=None):
    mod = types.ModuleType(nome)
    mod.__file__ = os.path.abspath(__file__)
    mod.__package__ = ""
    if extras:
        mod.__dict__.update(extras)
    mod.__dict__["_MOD"] = _MOD
    sys.modules[nome] = mod
    _MOD[nome] = mod
    exec(compile(fonte, "%s (embutido em %s)" % (nome, os.path.basename(__file__)),
                 "exec"), mod.__dict__)
    return mod


